cd /private/var/folders/yw/fbsfvfm95956m4m6yfd49z_c0000gn/T/tair-expanded-project-4yadkaw5/workspace && node --input-type=module -e "
import { uniqueStrings } from './unique_repeat.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const ra = uniqueStrings(a);
console.log('basic:', JSON.stringify(ra));
console.assert(JSON.stringify(ra) === JSON.stringify(['apple','banana','cherry']), 'basic failed');

// Case sensitivity
const b = ['A', 'a', 'A', 'b'];
const rb = uniqueStrings(b);
console.log('case:', JSON.stringify(rb));
console.assert(JSON.stringify(rb) === JSON.stringify(['A','a','b']), 'case failed');

// Whitespace not trimmed
const c = [' x', 'x', ' x'];
const rc = uniqueStrings(c);
console.log('whitespace:', JSON.stringify(rc));
console.assert(JSON.stringify(rc) === JSON.stringify([' x','x']), 'whitespace failed');

// Input not mutated
const d = ['p', 'q', 'p'];
const snapshot = JSON.stringify(d);
uniqueStrings(d);
console.assert(JSON.stringify(d) === snapshot, 'mutation detected');

// Empty input
console.log('empty:', JSON.stringify(uniqueStrings([])));

// All distinct
console.log('distinct:', JSON.stringify(uniqueStrings(['one','two','three'])));

console.log('All checks passed.');
"

